using System.ComponentModel;
using ModelContextProtocol.Server;
using MechCue;

[McpServerToolType]
public static class MachiningTools
{
    [McpServerTool(ReadOnly=true),Description("Screen a specified clearance seed hole and tapped seed hole in two assembly leaf keyPaths. Reads native hole frames/dimensions through references without opening child windows. Caller supplies boltDiameterMm, effective stackThicknessMm, boltUnderHeadLengthMm, requiredEngagementMm; optional headDiameterMm/headHeightMm and alignmentToleranceMm=.05. Reports coaxiality, axial order, clearance/thread diameter, available finite engagement/bottoming and counterbore head fit. Unknowns are not passes. Seed centers only, no pattern expansion, constraints, strength or tolerance certification.")]
    public static Task<string> solidedge_check_hole_interface(string expectedDocument,string firstKeyPath,string firstHoleName,string secondKeyPath,string secondHoleName,double boltDiameterMm,double stackThicknessMm,double boltUnderHeadLengthMm,double requiredEngagementMm,double headDiameterMm=0,double headHeightMm=0,double alignmentToleranceMm=.05)=>SolidEdgeTools.ExecuteCad("check-hole-interface",()=>Bridge.CadCheckHoleInterface(expectedDocument,firstKeyPath,firstHoleName,secondKeyPath,secondHoleName,boltDiameterMm,stackThicknessMm,boltUnderHeadLengthMm,requiredEngagementMm,headDiameterMm,headHeightMm,alignmentToleranceMm),false);
    [McpServerTool,Description("Edit native cosmetic internal thread data on an existing Ordered Hole, preserving profile/plane/extent/identity and dependent patterns. Exact threadDescription from list_metric_threads; empty removes thread. tapDrillDiameterMm positive within native minor/nominal bounds; threadDepthMm=0 full hole extent or positive finite length. Preserves counterbore/countersink seat and bottom angle. Shared HoleData refused; native Undo must be enabled. Uses native description lookup and reapplies the same HoleData to retain saved depth parameters. Verifies thread metadata and actual cylindrical bore; restores original values on failure via bounded native Undo/property snapshot. No save.")]
    public static Task<string> solidedge_set_hole_thread(string expectedDocument,string featureName,string threadDescription,double tapDrillDiameterMm,double threadDepthMm=0)=>SolidEdgeTools.ExecuteCad("set-hole-thread",()=>Bridge.CadSetHoleThread(expectedDocument,featureName,threadDescription,tapDrillDiameterMm,threadDepthMm));
    [McpServerTool(ReadOnly=true),Description("Read exact native feature dependencies and supported Ordered feature details: hole entry plane/centers/side, extruded cutout/protrusion depth/side and sketch lines/circles, or pattern inputs/count/spacing. Unknown curve kinds are not reconstructed. Does not modify CAD.")]
    public static Task<string> solidedge_get_feature_details(string expectedDocument,string featureName)=>SolidEdgeTools.ExecuteCad("feature-details",()=>Bridge.CadGetFeatureDetails(expectedDocument,featureName),false);
    [McpServerTool,Description("Edit an existing single-center native Ordered Hole, preserving identity and dependent patterns. changesJson is a partial object: diameterMm, finite depthMm, matching counterboreDiameterMm/counterboreDepthMm or countersinkDiameterMm/countersinkAngleDeg, finite threadDepthMm, centerXmm/centerYmm in existing plane. Positive machining sizes. Hole type/extent/plane/thread designation unchanged; tapped diameter must remain within native bounds. Checks health/retained values, restores old values on failure; no save. Shared HoleData refused.")]
    public static Task<string> solidedge_edit_hole(string expectedDocument,string featureName,string changesJson)=>SolidEdgeTools.ExecuteCad("edit-hole",()=>Bridge.CadEditHole(expectedDocument,featureName,changesJson));
    [McpServerTool,Description("Edit one-seed native Ordered hole pattern via changesJson: rectangular xCount/yCount/xSpacingMm/ySpacingMm, or circular radialCount/angleSpacingDeg. 2..256 instances; circular axis unchanged. Checks retained values and all feature health; restores old values on failure. No save; reread topology.")]
    public static Task<string> solidedge_edit_hole_pattern(string expectedDocument,string featureName,string changesJson)=>SolidEdgeTools.ExecuteCad("edit-hole-pattern",()=>Bridge.CadEditHolePattern(expectedDocument,featureName,changesJson));
    [McpServerTool,Description("Delete one named native Ordered Hole or Pattern only when native dependency query confirms no dependents. Does not cascade. backupPath must be an absolute new .par in an existing directory: saves recovery copy before deletion; checks only requested feature removed and all health. Uses native Undo on failure, reports backup if recovery fails. No source save. Delete dependent pattern explicitly before seed. Reread feature/topology keys.")]
    public static Task<string> solidedge_delete_machining_feature(string expectedDocument,string featureName,string backupPath)=>SolidEdgeTools.ExecuteCad("delete-machining-feature",()=>Bridge.CadDeleteMachiningFeature(expectedDocument,featureName,backupPath));
    [McpServerTool(ReadOnly=true),Description("Search/page exact metric straight thread descriptions and diameters from Solid Edge's configured legacy HoleSizeFile (.txt). descriptionContains is case-insensitive text; family exact case-insensitive native family; nominalDiameterMm=0 any diameter. AND filters, offset>=0, limit=1..1000; matchedCount/nextOffset report remaining matches. Requires CAD read permission. Not the newer XLSX standards catalog. Use descriptions exactly; tap drill diameter is selected by caller within native minor/nominal bounds.")]
    public static Task<string> solidedge_list_metric_threads(string descriptionContains="",string family="",double nominalDiameterMm=0,int offset=0,int limit=1000)=>SolidEdgeTools.ExecuteCad("list-metric-threads",()=>Bridge.CadListMetricThreads(descriptionContains,family,nominalDiameterMm,offset,limit),false);
    [McpServerTool,Description("Create a native Ordered Hole feature in a single-model .par. centersJson=[{x,y}] in plane-local mm, exactly ONE center; use pattern_hole for repeats. holeType regular/counterbore/countersink; extent through (one direction) or finite with depthMm. planeOffsetMm offsets selected plane along its normal; choose entry surface and direction positive/negative into solid. Countersink angle is degrees. Optional exact metric threadDescription from list_metric_threads creates native tapped-hole data; diameterMm is caller-selected tap drill diameter within native internal minor/nominal bounds. Uses configured legacy hole-size table. threadDepthMm=0 full hole extent, positive finite thread depth. Cosmetic internal threads only; no helical solid or external screw threads. Rejects unknown sizes; checks retained dimensions and all feature health, attempts cleanup on failure. Does not save.")]
    public static Task<string> solidedge_create_hole(string expectedDocument,string centersJson,double diameterMm,string holeType="regular",string extent="through",double depthMm=0,int planeNumber=1,double planeOffsetMm=0,string direction="positive",double counterboreDiameterMm=0,double counterboreDepthMm=0,double countersinkDiameterMm=0,double countersinkAngleDeg=90,string threadDescription="",double threadDepthMm=0,string featureName="")
        =>SolidEdgeTools.ExecuteCad("create-hole",()=>Bridge.CadCreateHole(expectedDocument,centersJson,diameterMm,holeType,extent,depthMm,planeNumber,planeOffsetMm,direction,counterboreDiameterMm,counterboreDepthMm,countersinkDiameterMm,countersinkAngleDeg,threadDescription,threadDepthMm,featureName));
    [McpServerTool(ReadOnly=true),Description("Read native Ordered Hole feature data: diameters/depths in mm, counterbore/countersink, native thread description/treatment/depth, extent and center count. diameterMm is native HoleDiameter (can represent nominal diameter after native thread edits); effectiveBoreDiameterMm follows native thread diameter option, plus threadTapDrillDiameterMm/threadNominalDiameterMm. Native nominal may be zero on legacy definitions. Cutouts are not reported as holes; pattern instances are represented by their native Pattern feature.")]
    public static Task<string> solidedge_list_holes(string expectedDocument)=>SolidEdgeTools.ExecuteCad("list-holes",()=>Bridge.CadListHoles(expectedDocument),false);
    [McpServerTool,Description("Create native rectangular/circular Pattern from one named native Hole containing one center. 2..256 total instances including seed; uses Solid Edge fixed spacing. Rectangular X/Y axes are selected reference-plane axes; rectangleAngleDeg rotation. Circular axis centerX/Y/Zmm is in document 3D coordinates, angleSpacingDeg positive, right curve direction; avoid duplicate 360-degree endpoint. Includes native seed feature dependency. Checks all feature health, attempts removal of only new patterns on failure. Does not save.")]
    public static Task<string> solidedge_pattern_hole(string expectedDocument,string sourceFeatureName,string patternType="rectangular",int xCount=2,int yCount=2,double xSpacingMm=20,double ySpacingMm=20,int radialCount=4,double angleSpacingDeg=90,int planeNumber=1,double centerXmm=0,double centerYmm=0,double centerZmm=0,double rectangleAngleDeg=0,string featureName="")
        =>SolidEdgeTools.ExecuteCad("pattern-hole",()=>Bridge.CadPatternHole(expectedDocument,sourceFeatureName,patternType,xCount,yCount,xSpacingMm,ySpacingMm,radialCount,angleSpacingDeg,planeNumber,centerXmm,centerYmm,centerZmm,rectangleAngleDeg,featureName));
    [McpServerTool,Description("Create native equal-setback (45-degree) Chamfer on explicit current edgeIdsJson from list_edges, 1..256 unique keys; setbackMm positive. Ordered single-model part. Validates keys before mutation; checks features and removes newly added chamfers on failure. No save. Re-read topology keys after edits.")]
    public static Task<string> solidedge_chamfer_edges(string expectedDocument,string edgeIdsJson,double setbackMm,string featureName="")=>SolidEdgeTools.ExecuteCad("chamfer-edges",()=>Bridge.CadChamferEdges(expectedDocument,edgeIdsJson,setbackMm,featureName));
    [McpServerTool(ReadOnly=true),Description("Read a named feature's sketch dimensions, driving flag, type and native variableName. Linear dimensions including circle diameters are in mm. Use on rectangle/circle extrusions created with drivingDimensions=true; not PMI reference annotations.")]
    public static Task<string> solidedge_list_profile_dimensions(string expectedDocument,string featureName)=>SolidEdgeTools.ExecuteCad("list-profile-dimensions",()=>Bridge.CadListProfileDimensions(expectedDocument,featureName),false);
    [McpServerTool,Description("Edit one named driving sketch dimension using exact variableName from list_profile_dimensions; valueMm positive. Intended for rectangle widths/heights and circle diameters. Recomputes, checks all features and requested value, attempts restore on failure. Does not save. Re-read edge/face IDs after change.")]
    public static Task<string> solidedge_set_profile_dimension(string expectedDocument,string featureName,string variableName,double valueMm)=>SolidEdgeTools.ExecuteCad("set-profile-dimension",()=>Bridge.CadSetProfileDimension(expectedDocument,featureName,variableName,valueMm));
}
